<?php
namespace App\Http\Controllers;use App\Http\Requests\StoreTrainingNeedRequest;use App\Models\{MatrizRiesgo,TrainingNeed};use App\Services\TrainingNeedService;use Illuminate\Http\Request;class TrainingNeedController extends Controller{public function index(){$needs=TrainingNeed::forCompany(auth()->user()->company_id)->with('risks')->latest()->get();$risks=MatrizRiesgo::where('company_id',auth()->user()->company_id)->get();return view('training.needs.index',compact('needs','risks'));}public function store(StoreTrainingNeedRequest$r,TrainingNeedService$s){$data=$r->validated();$risks=$data['risk_ids']??[];unset($data['risk_ids']);$s->create($data,$risks,$r->user()->id,$r->user()->company_id);return back()->with('success','Necesidad registrada.');}public function approve(TrainingNeed$n,Request$r,TrainingNeedService$s){$this->own($n);$s->approve($n,$r->user()->id);return back()->with('success','Necesidad aprobada para planificación.');}public function cancel(TrainingNeed$n,Request$r,TrainingNeedService$s){$this->own($n);$d=$r->validate(['reason'=>'required|string|min:10']);$s->cancel($n,$r->user()->id,$d['reason']);return back()->with('success','Necesidad cancelada con trazabilidad.');}private function own($n){abort_unless($n->company_id===auth()->user()->company_id,403);}}
